-- verify after 25 (SELECT only): every trimmed passage is <= 160 words and on an E1019-T* version
-- generated by scripts/prod-open/sat-trim160-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; new problem_versions only; no deletes/overwrites; set composition untouched.

select p.id as problem_id, pv.quality->'mockExamGeneration'->>'gid' as gid, pv.version_no, pv.quality->'auditFix'->>'patch' as patch, cardinality(regexp_split_to_array(trim(pv.passage), '\s+')) as words,
  cardinality(regexp_split_to_array(trim(pv.passage), '\s+')) <= 160 as within_160
from problems p join problem_versions pv on pv.id = p.published_version_id where p.id = any (array['829542e9-6519-4df6-bc6b-3cc5c712366a','cabe66af-bc8e-4a61-9266-8b64ba2439a0','7957cf07-7d69-4e64-8c53-d93aec2dd657','9955b04a-fd58-46e2-8211-baffdd5a7ecc','3f561501-398a-4ef0-b478-a6da114cd211','4f9809e4-8317-421e-86c8-f3e477f10c49','ef9d1b60-b642-43dc-9c2e-3ecd85dadf14','53d078fc-f658-4871-bbdb-f43ad359dc66','b9d75f29-d9e0-4f6c-b6bd-a5c306d30f41','ea780ed9-ebca-4582-b16a-97b8f2be1581']::uuid[]) order by 2;
